/* Котировки Московской биржи (открытый ISS API: iss.moex.com) и учёт портфеля.
   Функции в клетках: =КОТИРОВКА("SBER"; "цена"), =ЦЕНА_НА_ДАТУ("SBER"; ДАТА(2025;12;30)), =ДИВИДЕНДЫ("SBER"; 2025).
   Данные биржи — с задержкой и по её правилам использования; это не инвестиционная рекомендация. */
/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
const ISS = 'https://iss.moex.com';
const ДЕНЬ0 = Date.UTC(1899, 11, 30);
const вДату = n => new Date(ДЕНЬ0 + Math.round(n) * 86400000).toISOString().slice(0, 10);
const изДаты = s => { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? (Date.UTC(+m[1], +m[2] - 1, +m[3]) - ДЕНЬ0) / 86400000 : null; };
/* свой посредник: из поля панели, а в вызовах функций формул (панели может и не быть) — из хранилища */
function корень(){ let s = ''; try { s = String(параметры({}).сервер || '').trim(); } catch(e){} if(!s) s = String(хранилище.взять('сервер', '') || '').trim(); return s.replace(/\/+$/, '') || ISS; }
function СерверСменился(){ const s = String(параметры({}).сервер || '').trim(); хранилище.положить('сервер', s); МЕСТА.clear(); КОТ.clear(); панель.сообщение(s ? 'Запросы пойдут через ' + s : 'Запросы — прямо на iss.moex.com'); }
function Старт(){ const s = хранилище.взять('сервер', ''); if(s) панель.поле('сервер', s); }
/* ISS отдаёт таблицы «columns + data» — в записи */
function записи(блок){ if(!блок || !блок.columns) return []; return блок.data.map(r => { const о = {}; блок.columns.forEach((c, i) => о[c] = r[i]); return о; }); }
async function iss(путь, параметры2){
  const адрес = корень() + путь + (путь.includes('?') ? '&' : '?') + 'iss.meta=off' + (параметры2 ? '&' + параметры2 : '');
  const о = await запрос(адрес, {срок: 30000});
  if(!о.ок) throw new Error('Биржа ответила ' + о.код + (о.код === 0 ? ' (нет связи или адрес закрыт браузером: попробуйте свой посредник в настройках)' : ''));
  if(!о.тело) throw new Error('Биржа прислала не JSON');
  return о.тело;
}
/* где торгуется бумага: основной режим торгов */
const МЕСТА = new Map();
async function место(тикер){
  тикер = String(тикер || '').trim().toUpperCase();
  if(!тикер) throw new Error('Не указан тикер');
  if(МЕСТА.has(тикер)) return МЕСТА.get(тикер);
  const запас = хранилище.взять('места', null) || {};
  if(запас[тикер]){ МЕСТА.set(тикер, запас[тикер]); return запас[тикер]; }
  const т = await iss('/iss/securities/' + encodeURIComponent(тикер) + '.json', 'iss.only=boards,description');
  const режимы = записи(т.boards);
  if(!режимы.length) throw new Error('Бумаги «' + тикер + '» на Московской бирже нет');
  const осн = режимы.find(r => r.is_primary === 1 || r.is_primary === '1') || режимы.find(r => r.is_traded === 1) || режимы[0];
  const о = записи(т.description).reduce((a, r) => { a[r.name] = r.value; return a; }, {});
  const м = {тикер, движок: осн.engine, рынок: осн.market, режим: осн.boardid, тип: о.TYPE || '', группа: о.GROUP || '', название: о.SHORTNAME || о.NAME || тикер};
  МЕСТА.set(тикер, м); запас[тикер] = м; хранилище.положить('места', запас);
  return м;
}
/* котировка: бумага и рынок разом; запас на минуту — десяток клеток с одним тикером не ходят на биржу десять раз */
const КОТ = new Map();
async function котировка(тикер){
  const м = await место(тикер);
  const был = КОТ.get(м.тикер);
  if(был && Date.now() - был.когда < 60000) return был.ждём;
  const ждём = (async () => {
    const т = await iss('/iss/engines/' + м.движок + '/markets/' + м.рынок + '/boards/' + м.режим + '/securities/' + encodeURIComponent(м.тикер) + '.json', 'iss.only=securities,marketdata');
    const с = записи(т.securities)[0] || {}, р = записи(т.marketdata)[0] || {};
    return {м, с, р};
  })();
  КОТ.set(м.тикер, {когда: Date.now(), ждём});
  ждём.catch(() => КОТ.delete(м.тикер));
  return ждём;
}
const ПОЛЯ = ['цена', 'цена_руб', 'изменение', 'название', 'лот', 'валюта', 'открытие', 'минимум', 'максимум', 'вчера', 'оборот', 'время', 'номинал', 'нкд', 'купон', 'дата_купона', 'погашение', 'доходность', 'тип', 'режим'];
function поле(к, имя){
  const {м, с, р} = к, облиг = м.рынок === 'bonds';
  const цена = р.LAST ?? р.LCURRENTPRICE ?? р.MARKETPRICE ?? с.PREVPRICE ?? с.PREVWAPRICE ?? null;
  switch(имя){
    case 'цена': return цена;
    case 'цена_руб': return облиг && цена != null ? цена * (с.FACEVALUE || 1000) / 100 : цена;
    case 'изменение': return р.LASTTOPREVPRICE != null ? р.LASTTOPREVPRICE / 100 : (цена != null && с.PREVPRICE ? цена / с.PREVPRICE - 1 : null);
    case 'название': return с.SHORTNAME || м.название;
    case 'лот': return с.LOTSIZE ?? null;
    case 'валюта': return с.CURRENCYID || с.FACEUNIT || 'SUR';
    case 'открытие': return р.OPEN ?? null;
    case 'минимум': return р.LOW ?? null;
    case 'максимум': return р.HIGH ?? null;
    case 'вчера': return с.PREVPRICE ?? null;
    case 'оборот': return р.VALTODAY ?? null;
    case 'время': return р.UPDATETIME || р.TIME || '';
    case 'номинал': return с.FACEVALUE ?? null;
    case 'нкд': return с.ACCRUEDINT ?? null;
    case 'купон': return с.COUPONVALUE ?? null;
    case 'дата_купона': return изДаты(с.NEXTCOUPON);
    case 'погашение': return изДаты(с.MATDATE);
    case 'доходность': return р.YIELD != null ? р.YIELD / 100 : (с.YIELDATPREVWAPRICE != null ? с.YIELDATPREVWAPRICE / 100 : null);
    case 'тип': return облиг ? 'Облигации' : м.движок === 'currency' ? 'Валюта' : /etf|ppif|fund/i.test(м.тип + м.группа) || /^TQTF|^TQIF/.test(м.режим) ? 'Фонды' : 'Акции';
    case 'режим': return м.режим;
  }
  throw new Error('Поле «' + имя + '» неизвестно. Есть: ' + ПОЛЯ.join(', '));
}
/* ---------- функции формул (живой поток плагина, с сетью) ---------- */
async function Котировка(тикер, имя){
  const к = await котировка(тикер);
  const v = поле(к, String(имя || 'цена').trim().toLowerCase());
  if(v === null || v === undefined) throw new Error('Биржа не дала «' + (имя || 'цена') + '» для ' + к.м.тикер + ' (торгов могло не быть)');
  return v;
}
async function история(тикер, от, до){
  const м = await место(тикер);
  const out = [];
  for(let start = 0; start < 20000; start += 100){
    const т = await iss('/iss/history/engines/' + м.движок + '/markets/' + м.рынок + '/boards/' + м.режим + '/securities/' + encodeURIComponent(м.тикер) + '.json',
      'from=' + от + '&till=' + до + '&start=' + start + '&history.columns=TRADEDATE,OPEN,LOW,HIGH,CLOSE,VOLUME,VALUE,LEGALCLOSEPRICE');
    const з = записи(т.history);
    out.push(...з);
    if(з.length < 100) break;
  }
  return {м, ряды: out};
}
async function ЦенаНаДату(тикер, дата){
  const d = typeof дата === 'number' ? дата : изДаты(String(дата));
  if(d == null) throw new Error('Дата — числом таблицы или «ГГГГ-ММ-ДД»');
  /* торгов в этот день могло не быть — берём последний торговый день до даты */
  const {ряды} = await история(тикер, вДату(d - 10), вДату(d));
  const есть = ряды.filter(r => (r.CLOSE ?? r.LEGALCLOSEPRICE) != null);
  if(!есть.length) throw new Error('Нет торгов ' + тикер + ' за 10 дней до ' + вДату(d));
  const r = есть[есть.length - 1];
  return r.CLOSE ?? r.LEGALCLOSEPRICE;
}
async function Дивиденды(тикер, год){
  const т = await iss('/iss/securities/' + encodeURIComponent(String(тикер).trim().toUpperCase()) + '/dividends.json');
  const з = записи(т.dividends);
  const г = Math.round(+год || new Date().getFullYear());
  return з.filter(r => String(r.registryclosedate || '').startsWith(String(г))).reduce((a, r) => a + (+r.value || 0), 0);
}

/* ---------- команды ---------- */
async function безСбоя(f){ try { return await f(); } catch(e){ панель.сообщение(e.message); панель.поле('итог', [{текст: e.message, цвет: '#c92a2a'}]); } }
function тикеры(){
  const т = String(параметры({}).тикеры || '').trim();
  if(т) return т.split(/[\s,;]+/).filter(Boolean).map(x => x.toUpperCase());
  const в = книга.выделение;
  const out = [];
  if(в) for(let r = в.r1; r <= в.r2; r++) for(let c = в.c1; c <= в.c2; c++){ const v = ячейка(r, c).значение; if(typeof v === 'string' && /^[A-Z0-9-]{2,20}$/i.test(v.trim())) out.push(v.trim().toUpperCase()); }
  return out;
}
async function Котировки(){ return безСбоя(async () => {
  const сп = [...new Set(тикеры())];
  if(!сп.length) throw new Error('Впишите тикеры в поле (SBER, GAZP, SU26238RMFS4) или выделите клетки с ними');
  const в = книга.выделение, r0 = в.r2 - 1, c0 = в.c1 - 1;          /* r0 + 1 — строка сразу под выделением (с нуля) */
  const ряды = [['Тикер', 'Название', 'Цена', 'Изменение', 'Открытие', 'Минимум', 'Максимум', 'Оборот, ₽', 'Время', 'Тип']];
  const беды = [];
  for(const т of сп){
    try { const к = await котировка(т); ряды.push([т, поле(к, 'название'), поле(к, 'цена'), поле(к, 'изменение'), поле(к, 'открытие'), поле(к, 'минимум'), поле(к, 'максимум'), поле(к, 'оборот'), поле(к, 'время'), поле(к, 'тип')]); }
    catch(e){ беды.push(т + ': ' + e.message); ряды.push([т, e.message, null, null, null, null, null, null, null, null]); }
  }
  const режим = параметры({}).формулами !== false;
  диапазон(ОБЛАСТЬ(r0 + 1, c0, r0 + ряды.length, c0 + 9)).записать(ряды.map((р, i) => i && режим ? [р[0], р[1], null, null, р[4], р[5], р[6], р[7], р[8], р[9]] : р));
  if(режим) ряды.slice(1).forEach((р, i) => { клетка(r0 + 2 + i, c0 + 2).формула = 'КОТИРОВКА(' + АДРЕС(r0 + 2 + i, c0) + ';"цена")'; клетка(r0 + 2 + i, c0 + 3).формула = 'КОТИРОВКА(' + АДРЕС(r0 + 2 + i, c0) + ';"изменение")'; });
  for(let c = 0; c < 10; c++) клетка(r0 + 1, c0 + c).стиль = {b: 1, fill: '#e7eef9'};
  try { const л = Api.GetActiveSheet(); оформитьОбласть(лист(), r0 + 1, c0 + 3, r0 + ряды.length - 1, c0 + 3, {fmt: '0.00%'});
    const у = л.GetRange(ОБЛАСТЬ(r0 + 2, c0 + 3, r0 + ряды.length, c0 + 3)).GetFormatConditions();
    const у1 = у.Add('xlCellValue', 'xlLess', '0'); у1.SetFontColor(Api.CreateColorFromRGB(201, 42, 42)); у1.SetFillColor('No Fill'); const у2 = у.Add('xlCellValue', 'xlGreater', '0'); у2.SetFontColor(Api.CreateColorFromRGB(43, 138, 62)); у2.SetFillColor('No Fill');
    оформитьОбласть(лист(), r0 + 1, c0 + 7, r0 + ряды.length - 1, c0 + 7, {fmt: '#,##0'}); } catch(e){}
  панель.поле('итог', [{текст: 'Котировок: ' + (сп.length - беды.length) + ' из ' + сп.length, жирный: true}].concat(беды.length ? [{текст: '. ' + беды.join('; '), цвет: '#c92a2a'}] : [{текст: режим ? '. Цена и изменение — формулами =КОТИРОВКА(): «Данные → Обновить функции» запросит заново.' : ''}]));
}); }
async function История(){ return безСбоя(async () => {
  const п = параметры({}), т = (тикеры()[0] || '').toUpperCase();
  if(!т) throw new Error('Укажите тикер');
  const от = String(п.от || '').trim() || вДату((Date.now() - ДЕНЬ0) / 86400000 - 365), до = String(п.до || '').trim() || вДату((Date.now() - ДЕНЬ0) / 86400000);
  const {м, ряды} = await история(т, от, до);
  if(!ряды.length) throw new Error('Торгов ' + т + ' с ' + от + ' по ' + до + ' нет');
  const имя = т + ' — история';
  const л = await книга.черновик(имя.slice(0, 31));
  const табл = [['Дата', 'Открытие', 'Минимум', 'Максимум', 'Закрытие', 'Объём, шт.', 'Оборот, ₽']].concat(ряды.map(r => [String(r.TRADEDATE), r.OPEN, r.LOW, r.HIGH, r.CLOSE ?? r.LEGALCLOSEPRICE, r.VOLUME, r.VALUE]));
  л.диапазон(ОБЛАСТЬ(0, 0, табл.length - 1, 6)).записать(табл.map((р, i) => i ? [изДаты(р[0])].concat(р.slice(1)) : р));
  for(let c = 0; c < 7; c++) л.ячейка(1, c + 1).стиль = {b: 1, fill: '#e7eef9'};
  try {
    const api = Api.GetSheet(имя.slice(0, 31));
    оформитьОбласть(л, 1, 0, табл.length - 1, 0, {fmt: 'dd.mm.yyyy'}); api.GetRange('A1:G1').SetColumnWidth(13);
    /* график закрытия: даты подписями (текстом), цены рядом */
    л.диапазон(ОБЛАСТЬ(0, 9, табл.length - 1, 10)).записать([['Дата', 'Закрытие']].concat(табл.slice(1).map(р => [р[0].split('-').reverse().join('.'), р[4]])));
    const д = api.AddChart(ОБЛАСТЬ(0, 9, табл.length - 1, 10), false, 'lineNormal', 2, 6300000, 3200000, 9, 0, 1, 0);
    if(д && д.SetTitle) д.SetTitle(м.название + ': закрытие', 11);
  } catch(e){ сообщить('график: ' + e.message); }
  книга.выделить(имя.slice(0, 31) + '!A1');
