/* выплаты: дивиденды и купоны по тикерам из поля или выделения */
async function Выплаты(){ return безСбоя(async () => {
  const сп = [...new Set(тикеры())];
  if(!сп.length) throw new Error('Укажите тикеры');
  const сег = (Date.now() - ДЕНЬ0) / 86400000, ряды = [['Тикер', 'Вид', 'Дата', 'На одну бумагу', 'Валюта']];
  for(const т of сп){
    const м = await место(т);
    if(м.рынок === 'bonds'){
      const д = await iss('/iss/statistics/engines/stock/markets/bonds/bondization/' + encodeURIComponent(т) + '.json', 'iss.only=coupons,amortizations&limit=unlimited');
      for(const к of записи(д.coupons)){ const d = изДаты(к.coupondate); if(d >= сег - 1) ряды.push([т, 'купон', d, к.value, к.faceunit || 'RUB']); }
      for(const а of записи(д.amortizations)){ const d = изДаты(а.amortdate); if(d >= сег - 1 && а.value) ряды.push([т, 'погашение номинала', d, а.value, а.faceunit || 'RUB']); }
    } else {
      const д = await iss('/iss/securities/' + encodeURIComponent(т) + '/dividends.json');
      for(const r of записи(д.dividends).slice(-6)) ряды.push([т, 'дивиденд (отсечка)', изДаты(r.registryclosedate), r.value, r.currencyid || 'RUB']);
    }
  }
  const в = книга.выделение;
  const л = await книга.черновик('Выплаты');
  л.диапазон(ОБЛАСТЬ(0, 0, ряды.length - 1, 4)).записать(ряды.map((р, i) => i ? р : р));
  for(let c = 0; c < 5; c++) л.ячейка(1, c + 1).стиль = {b: 1, fill: '#e7eef9'};
  try { const api = Api.GetSheet('Выплаты'); оформитьОбласть(л, 1, 2, ряды.length - 1, 2, {fmt: 'dd.mm.yyyy'}); api.GetRange('A1:E1').SetColumnWidth(16); } catch(e){}
  книга.выделить('Выплаты!A1');
  панель.поле('итог', [{текст: 'Выплат: ' + (ряды.length - 1) + ' — на черновом листе «Выплаты». Дивиденды — прошлые и объявленные отсечки, купоны и погашения — будущие.', жирный: true}]);
}); }
